export const pageHtml = "    <!-- Mobile nav toggle -->\n    <button\n      id=\"nav-toggle\"\n      aria-label=\"Toggle navigation\"\n    >\n      &#9776;\n    </button>\n\n    <!-- Sidebar Navigation -->\n    <nav id=\"sidebar\">\n      <div class=\"nav-header\">\n        <a\n          href=\"#page-01\"\n          class=\"nav-sigil nav-link\"\n          aria-label=\"Go to title page\"\n          >✦</a\n        >\n        <div class=\"nav-title\">\n          The Kingdom <br />of the\n          Gods:<br />\n          Invisible Realms\n        </div>\n      </div>\n      <ul>\n        <li>\n          <a\n            href=\"#page-02\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >02</span\n            >\n            Geoffrey Hodson</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-03\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >03</span\n            >\n            Jeffrey Mishlove</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-04\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >04</span\n            >\n            What Are the Gods?</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-05\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >05</span\n            >\n            The Lesser Gods</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-06\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >06</span\n            >\n            Fairy Pancakes</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-07\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >07</span\n            >\n            The Mineral Kingdom</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-08\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >08</span\n            >\n            The Plant Kingdom</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-09\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >09</span\n            >\n            The Greater Gods</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-10\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >10</span\n            >\n            The Mountain Gods</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-14\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >11</span\n            >\n            The Insect Kingdom</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-11\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >12</span\n            >\n            Angelic Hierarchies</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-12\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >13</span\n            >\n            Angelic Healing</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-13\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >14</span\n            >\n            The Miracle of Birth</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-16\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >15</span\n            >\n            Rediscovering the Hidden\n            Kingdoms</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-17\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >16</span\n            >\n            L'Envoi</a\n          >\n        </li>\n        <li>\n          <a\n            href=\"#page-18\"\n            class=\"nav-link\"\n            ><span class=\"nav-num\"\n              >17</span\n            >\n            References</a\n          >\n        </li>\n      </ul>\n    </nav>\n\n    <!-- Main Content -->\n    <main>\n      <!-- HERO -->\n      <header\n        class=\"hero\"\n        id=\"page-01\"\n      >\n        <p class=\"hero-eyebrow\">\n          A Theosophical Exploration\n        </p>\n        <h1>\n          The Kingdom of the Gods:<br /><em\n            >Invisible Realms</em\n          >\n        </h1>\n        <div class=\"hero-rule\"></div>\n        <p class=\"hero-subtitle\">\n          Based on the clairvoyant\n          research of Geoffrey Hodson\n        </p>\n      </header>\n\n      <!-- ============================================================\n         PAGE 2 - Introduction to Geoffrey Hodson\n         ============================================================ -->\n      <section\n        class=\"page-section\"\n        id=\"page-02\"\n      >\n        <div class=\"section-header\">\n          <span class=\"section-num\"\n            >Page 02</span\n          >\n          <h2>Geoffrey Hodson</h2>\n          <div\n            class=\"section-rule\"\n          ></div>\n        </div>\n\n        <div class=\"section-body\">\n          <div\n            style=\"\n              display: grid;\n              grid-template-columns: 1fr 2fr;\n              gap: 2rem;\n              align-items: start;\n            \"\n          >\n            <img\n              src=\"images/geoffrey-hodson.jpg\"\n              alt=\"Geoffrey Hodson\"\n              style=\"\n                width: 100%;\n                height: 520px;\n                object-fit: cover;\n                object-position: center\n                  top;\n                border-radius: 6px;\n                border: 1px solid\n                  var(--border);\n              \"\n            />\n            <div class=\"bio-card-body\">\n              <h3>Geoffrey Hodson</h3>\n              <p>\n                GEOFFREY HODSON was born\n                and educated in England.\n                During the First World\n                War he served with\n                distinction in the\n                British Army and\n                afterwards became\n                actively interested in\n                Theosophical studies. He\n                carried out occult\n                research in\n                collaboration with\n                doctors, physicists,\n                anthropologists and\n                archeologists. For over\n                60 years Mr. Hodson\n                lectured for the\n                Theosophical Society,\n                speaking in America,\n                England, Europe, South\n                Africa, India, New\n                Zealand, Australia and\n                the Far East. He was the\n                author of about 40\n                books, dealing with\n                topics such as\n                meditation, the\n                spiritual life, health\n                and disease, and the\n                life and powers of the\n                occultist. He carried\n                out special and\n                first-hand\n                investigations of\n                fairies and angelic\n                evolution. Mr. Hodson\n                was 4 times Director of\n                Studies at the School of\n                the Wisdom at the\n                International\n                Headquarters of the\n                Theosophical Society,\n                Adyar, Chennai. He was\n                awarded the\n                <a\n                  href=\"https://theosophy.world/encyclopedia/subba-row-medal\"\n                  target=\"_blank\"\n                  rel=\"noopener noreferrer\"\n                  >Subba Row Medal</a\n                >\n                in 1954 for his\n                contributions to\n                Theosophical literature.\n              </p>\n              <p\n                style=\"margin-top: 1rem\"\n              >\n                <a\n                  href=\"https://www.theosophy.world/sites/default/files/ebooks/The%20Kingdom%20of%20the%20Gods%20-%20Geoffrey%20Hodson.pdf\"\n                  target=\"_blank\"\n                  rel=\"noopener noreferrer\"\n                  >The Kingdom of the\n                  Gods PDF</a\n                >\n              </p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 3 - Jeffrey Mishlove\n         ============================================================ -->\n      <section\n        class=\"page-section\"\n        id=\"page-03\"\n      >\n        <div class=\"section-header\">\n          <span class=\"section-num\"\n            >Page 03</span\n          >\n          <h2>Jeffrey Mishlove</h2>\n          <div\n            class=\"section-rule\"\n          ></div>\n        </div>\n        <div class=\"section-body\">\n          <div\n            style=\"\n              display: grid;\n              grid-template-columns: 1fr 2fr;\n              gap: 2rem;\n              align-items: start;\n            \"\n          >\n            <div class=\"bio-video bio-video-panel\">\n              <div class=\"video-container\">\n                <iframe\n                  src=\"https://www.youtube.com/embed/7WGssopZcig\"\n                  title=\"Watch Jeffrey Mishlove on Geoffrey Hodson\"\n                  allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\n                  referrerpolicy=\"strict-origin-when-cross-origin\"\n                  allowfullscreen\n                ></iframe>\n              </div>\n              <p class=\"video-label\">\n                New Thinking Allowed,\n                approx. 15 minutes.\n              </p>\n            </div>\n            <div class=\"bio-card-body\">\n              <h3>Jeffrey Mishlove</h3>\n              <p>\n                JEFFREY MISHLOVE is an\n                American\n                parapsychologist,\n                author, and television\n                host best known for his\n                long-running interview\n                series\n                <em\n                  >Thinking Allowed</em\n                >\n                and its successor\n                <a\n                  href=\"https://www.youtube.com/@NewThinkingAllowed\"\n                  target=\"_blank\"\n                  rel=\"noopener noreferrer\"\n                  ><em\n                    >New Thinking\n                    Allowed</em\n                  ></a\n                >, in which he explores\n                consciousness, psychic\n                phenomena, and human\n                potential with leading\n                researchers and\n                thinkers. He holds a\n                unique distinction as\n                the only person to earn\n                a doctoral degree in\n                parapsychology from an\n                accredited American\n                university (UC Berkeley,\n                1980). He is widely\n                respected in the field\n                for bringing rigorous,\n                open-minded inquiry to\n                topics that mainstream\n                academia often\n                dismisses.\n              </p>\n              \n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 4 - What Are the Gods?\n         ============================================================ -->\n      <section\n        class=\"page-section layout-image-right\"\n        id=\"page-04\"\n      >\n        <div class=\"section-panel-text\">\n          <div class=\"section-header\">\n            <span class=\"section-num\"\n              >Page 04</span\n            >\n            <h2>What Are the Gods?</h2>\n            <div\n              class=\"section-rule\"\n            ></div>\n          </div>\n\n          <div class=\"section-body\">\n            <div\n              class=\"section-content\"\n            >\n              <ul\n                style=\"line-height: 1\"\n              >\n                <li\n                  style=\"\n                    margin-bottom: 0.3rem;\n                  \"\n                >\n                  The Devic Kingdom\n                </li>\n                <li\n                  style=\"\n                    margin-bottom: 0.3rem;\n                  \"\n                >\n                  Hierarchical Orders of\n                  Intelligences distinct\n                  from humanity\n                </li>\n                <li\n                  style=\"\n                    margin-bottom: 0.3rem;\n                  \"\n                >\n                  Made up of Lesser and\n                  Greater Gods\n                </li>\n                <li\n                  style=\"\n                    margin-bottom: 0.3rem;\n                  \"\n                >\n                  Profoundly responsive\n                  to human thought and\n                  emotion\n                </li>\n                <li\n                  style=\"\n                    margin-bottom: 0.3rem;\n                  \"\n                >\n                  Genderless but they do\n                  express polarities\n                </li>\n              </ul>\n              \n            </div>\n          </div>\n          <div class=\"speaker-notes\">\n            <p class=\"notes-label\">\n              PLATE 18\n            </p>\n            <p>\n              <em\n                >\"The unusual, pointed,\n                oval shape produced by\n                the flowing streams of\n                its auric forces was\n                clearly discernible. As\n                the picture shows, great\n                currents of power\n                descend upon this sea\n                God, are compressed\n                within its aura and then\n                released into the ocean\n                beneath. This being is\n                subordinate to a still\n                greater God, responsible\n                for the whole Pacific\n                Ocean.\"</em\n              >\n            </p>\n          </div>\n        </div>\n        <div\n          class=\"section-panel-image\"\n        >\n          <img\n            src=\"images/plate-dee04121-fa1a-4dd7-ad9a-bbd545dd7990.png\"\n            alt=\"Plate 18: A God of the Southern Pacific - The Kingdom of the Gods, illustrated by Ethelwynne M. Quail\"\n          />\n          <div\n            class=\"panel-caption plate-trigger\"\n          >\n            PLATE 18 - A GOD OF THE\n            SOUTHERN PACIFIC\n          </div>\n        </div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 5 - The Lesser Gods\n         ============================================================ -->\n      <section\n        class=\"page-section\"\n        id=\"page-05\"\n      >\n        <div class=\"section-header\">\n          <span class=\"section-num\"\n            >Page 05</span\n          >\n          <h2>The Lesser Gods</h2>\n          <div\n            class=\"section-rule\"\n          ></div>\n        </div>\n\n        <div\n          class=\"section-body elemental-carousel-body\"\n        >\n          <p class=\"elemental-intro\">\n            The Lesser Gods are the\n            Elementals, the Nature\n            Spirits, most closely\n            associated with the four\n            classical elements. They are\n            the builders, the unseen\n            workforce of the natural\n            world - constructing the\n            forms of minerals, plants,\n            animals, and weather;\n            directing the growth of\n            roots and crystals; guiding\n            the movement of water and\n            flame.\n            Reference\n            <a\n              href=\"https://www.amazon.com/Fairies-Work-Play-Quest-Book/dp/0835605531\"\n              target=\"_blank\"\n              rel=\"noopener noreferrer\"\n              >Fairies at Work and at\n              Play by Geoffrey Hodson,\n              1925</a\n            >.\n          </p>\n                      <div\n            class=\"elemental-carousel\"\n          >\n            <div\n              class=\"carousel-track\"\n              id=\"elemental-track\"\n            >\n              <div\n                class=\"carousel-slide\"\n              >\n                <div\n                  class=\"carousel-slide-text\"\n                >\n                  <span\n                    class=\"element-tag\"\n                    >Air</span\n                  >\n                  <h4>\n                    Sylphs and Fairies\n                  </h4>\n                  <p>\n                    The elementals of\n                    air - swift, light,\n                    and mercurial.\n                    Sylphs and fairies\n                    are associated with\n                    wind, breath,\n                    thought, and the\n                    upper atmosphere.\n                    They assist in the\n                    movement of pollen,\n                    the dispersal of\n                    seeds, and the\n                    formation of clouds.\n                    Their forms, as\n                    perceived\n                    clairvoyantly, often\n                    suggest feathers,\n                    wings, or streaming\n                    ribbons of light.\n                  </p>\n                </div>\n                <div\n                  class=\"carousel-slide-image\"\n                >\n                  <img\n                    src=\"images/plate-f532d61e-3881-4af1-ba7e-a3a0762fbbda.png\"\n                    alt=\"Sylph - Air elemental, illustrated by Geoffrey Hodson\"\n                  />\n                  <div class=\"panel-caption\">\n                    PLATE 2\n                  </div>\n                </div>\n              </div>\n              <div\n                class=\"carousel-slide\"\n              >\n                <div\n                  class=\"carousel-slide-text\"\n                >\n                  <span\n                    class=\"element-tag\"\n                    >Fire</span\n                  >\n                  <h4>Salamanders</h4>\n                  <p>\n                    The elementals of\n                    fire - intense,\n                    rapid, and\n                    transformative.\n                    Salamanders inhabit\n                    every form of flame,\n                    from a candle to the\n                    solar corona. They\n                    are the builders of\n                    heat and light, the\n                    agents of combustion\n                    and purification.\n                    Their forms often\n                    resemble sinuous\n                    tongues of flame or\n                    compact, darting\n                    creatures of intense\n                    radiance.\n                  </p>\n                </div>\n                <div\n                  class=\"carousel-slide-image\"\n                >\n                  <img\n                    src=\"images/plate-8ec1bfe5-2e13-41c9-853f-bc8cbb52ac15.png\"\n                    alt=\"Salamander - Fire elemental, illustrated by Geoffrey Hodson\"\n                  />\n                  <div class=\"panel-caption\">\n                    PLATE 3\n                  </div>\n                </div>\n              </div>\n              <div\n                class=\"carousel-slide\"\n              >\n                <div\n                  class=\"carousel-slide-text\"\n                >\n                  <span\n                    class=\"element-tag\"\n                    >Water</span\n                  >\n                  <h4>\n                    Undines and Nereids\n                  </h4>\n                  <p>\n                    The elementals of\n                    water - fluid,\n                    reflective, and\n                    emotionally\n                    resonant. Undines\n                    and nereids inhabit\n                    oceans, rivers,\n                    lakes, rain, and the\n                    moisture in soil and\n                    living tissue. They\n                    direct the tidal\n                    movements of the\n                    earth's water body\n                    and are responsible\n                    for the forms taken\n                    by water in its many\n                    states. Their\n                    appearances range\n                    from simple\n                    sea-forms to\n                    graceful flowing\n                    figures.\n                  </p>\n                </div>\n                <div\n                  class=\"carousel-slide-image\"\n                >\n                  <img\n                    src=\"images/plate-5e0e3a9d-c8e8-4cb6-9f23-0637fe2d6110.png\"\n                    alt=\"Undine - Water elemental, illustrated by Geoffrey Hodson\"\n                  />\n                  <div class=\"panel-caption\">\n                    PLATE 4\n                  </div>\n                </div>\n              </div>\n              <div\n                class=\"carousel-slide\"\n              >\n                <div\n                  class=\"carousel-slide-text\"\n                >\n                  <span\n                    class=\"element-tag\"\n                    >Earth</span\n                  >\n                  <h4>\n                    Brownies and Gnomes\n                  </h4>\n                  <p>\n                    The elementals of\n                    earth - dense,\n                    deliberate, and\n                    immensely strong.\n                    Brownies and gnomes\n                    work within soil,\n                    rock, crystal, and\n                    the root systems of\n                    plants. Their forms\n                    often appear\n                    angular, knotted,\n                    and closely bound to\n                    the earth they\n                    inhabit.\n                  </p>\n                </div>\n                <div\n                  class=\"carousel-slide-image\"\n                >\n                  <img\n                    src=\"images/earth-gnome.jpg\"\n                    alt=\"Earth Gnome - Earth elemental, illustrated by Geoffrey Hodson\"\n                  />\n                </div>\n              </div>\n            </div>\n            <div\n              class=\"carousel-controls\"\n            >\n              <button\n                class=\"carousel-btn\"\n                id=\"elem-prev\"\n                onclick=\"window.__hiddenArchitectsGoElemental && window.__hiddenArchitectsGoElemental(-1); return false;\"\n              >\n                ◀\n              </button>\n              <div\n                class=\"carousel-dots\"\n              >\n                <span\n                  class=\"elem-dot active\"\n                  data-idx=\"0\"\n                  onclick=\"window.__hiddenArchitectsGoElemental && window.__hiddenArchitectsGoElemental(0, true); return false;\"\n                ></span>\n                <span\n                  class=\"elem-dot\"\n                  data-idx=\"1\"\n                  onclick=\"window.__hiddenArchitectsGoElemental && window.__hiddenArchitectsGoElemental(1, true); return false;\"\n                ></span>\n                <span\n                  class=\"elem-dot\"\n                  data-idx=\"2\"\n                  onclick=\"window.__hiddenArchitectsGoElemental && window.__hiddenArchitectsGoElemental(2, true); return false;\"\n                ></span>\n                <span\n                  class=\"elem-dot\"\n                  data-idx=\"3\"\n                  onclick=\"window.__hiddenArchitectsGoElemental && window.__hiddenArchitectsGoElemental(3, true); return false;\"\n                ></span>\n              </div>\n              <button\n                class=\"carousel-btn\"\n                id=\"elem-next\"\n                onclick=\"window.__hiddenArchitectsGoElemental && window.__hiddenArchitectsGoElemental(1); return false;\"\n              >\n                ▶\n              </button>\n            </div>\n          </div>\n        </div>\n        <div class=\"speaker-notes\">\n          <p class=\"notes-label\">\n            05 / 18 - Nature Spirits -\n            The Builders\n          </p>\n          <p>\n            What are Nature Spirits?\n            Nature spirits are beings\n            belonging to the elemental\n            kingdoms - conscious,\n            non-human entities that\n            inhabit and animate the four\n            classical elements of earth,\n            water, fire, and air. They\n            are the invisible labourers\n            of the natural world:\n            building, sustaining, and\n            dissolving the forms of\n            nature in ceaseless\n            activity. They are not\n            individualized in the way\n            humans are; they operate\n            more like currents of\n            life-energy shaped into\n            temporary forms, carrying\n            out the patterns imposed on\n            them by the higher deva\n            intelligences above them.\n          </p>\n          <p>\n            Recognized across virtually\n            every culture in human\n            history - as fairies,\n            brownies and gnomes,\n            sprites, sylphs and fairies,\n            salamanders, undines and\n            nereids, and a thousand\n            other names - nature spirits\n            have been perceived and\n            described long before\n            Theosophy gave them a\n            systematic framework.\n          </p>\n          <p>\n            What are Devas? Devas - from\n            the Sanskrit deva, meaning\n            <em>\"shining one\"</em> - are\n            the architects and overseers\n            of the natural world. Where\n            nature spirits build, devas\n            design. They represent a\n            parallel evolutionary\n            hierarchy alongside\n            humanity, ranging from the\n            guardian angels of\n            individual beings to the\n            vast cosmic intelligences\n            presiding over continents,\n            oceans, and the forces of\n            planetary life. In Western\n            traditions they are known as\n            angels. In Hindu cosmology\n            there are said to be 330\n            million of them. In\n            Theosophical teaching, they\n            include the great beings who\n            work with the Masters of\n            Wisdom in the spiritual\n            government of the world.\n          </p>\n          <p>\n            How are they similar? How\n            are they different? Both\n            kingdoms are real,\n            non-human, and conscious.\n            Both are far older in their\n            evolutionary lineage than\n            the human kingdom. Both are\n            profoundly responsive to\n            human thought and emotion -\n            a fact with deep\n            implications for how we\n            live.\n          </p>\n          <p>\n            The difference is one of\n            order and function. Nature\n            spirits are the builders -\n            elemental, relatively simple\n            in consciousness, responsive\n            to instruction. Devas are\n            the architects -\n            individualized, radiant with\n            intelligence, working with\n            purpose and design. If\n            nature spirits are the\n            workers, devas are the\n            master builders. Together\n            they constitute what Hodson\n            called the hidden side of\n            nature - the living\n            intelligence behind every\n            form in the natural world.\n          </p>\n        </div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 6 - Fairy Pancakes\n         ============================================================ -->\n      <section\n        class=\"page-section fairies-page\"\n        id=\"page-06\"\n      >\n        <div class=\"section-header\">\n          <span class=\"section-num\"\n            >Page 06</span\n          >\n          <h2>Fairy Pancakes</h2>\n          <div\n            class=\"section-rule\"\n          ></div>\n        </div>\n\n        <div class=\"section-body fairies-grid\">\n          <p class=\"fairies-intro\">\n            In his 1969 book\n            <a\n              href=\"https://www.amazon.com/Passport-Magonia-Folklore-Flying-Saucers-ebook/dp/B00TU7V0XA?ref_=ast_author_mpb\"\n              target=\"_blank\"\n              rel=\"noopener noreferrer\"\n              ><em>Passport to Magonia:\n              From Folklore to Flying\n              Saucers</em></a\n            >, Jacques Vallee, a\n            French computer scientist\n            and ufologist, poses a\n            theory that perhaps the\n            alien encounters of today\n            are the fairy and other\n            folklore encounters of the\n            past. Hodson says the\n            etheric form of Nature\n            Spirits is governed by at\n            least 3 influences: the\n            archetype, the element, and\n            <em>&quot;human habits, the\n            dress and the popular thought\n            concerning the appearance of\n            fairy people of particular\n            times and places.&quot;</em>\n            The poem <em>The Fairies</em>\n            by William Allingham, 1850.\n          </p>\n          <div class=\"fairies-media\">\n            <div class=\"video-container fairies-video\">\n              <iframe\n                src=\"https://www.youtube.com/embed/5L1p4uXcJKo?si=CmnPh4tXjP4dmB_d\"\n                title=\"YouTube video player\"\n                frameborder=\"0\"\n                allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\n                referrerpolicy=\"strict-origin-when-cross-origin\"\n                allowfullscreen\n              ></iframe>\n            </div>\n          </div>\n          <div class=\"section-content\">\n            <blockquote class=\"fairies-poem\">\n              <p>\n                Up the airy mountains,<br />\n                Down the rushy glen,<br />\n                We daren't go a-hunting<br />\n                For fear of little men;<br />\n                Wee folk, good folk,<br />\n                Trooping all together;<br />\n                Green jacket, red cap,<br />\n                And white owl's feather!\n              </p>\n              <p>\n                Down along the rocky shore<br />\n                Some make their home,<br />\n                They live on crispy pancakes<br />\n                Of yellow tide foam;<br />\n                Some in the reeds<br />\n                Of the black mountain lake,<br />\n                With frogs for their watch-dogs,<br />\n                All night awake.\n              </p>\n            </blockquote>\n          </div>\n\n        </div>\n        <div\n          class=\"speaker-notes\"\n        ></div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 7 - The Mineral Kingdom\n         ============================================================ -->\n      <section\n        class=\"page-section layout-image-right\"\n        id=\"page-07\"\n      >\n        <div class=\"section-panel-text\">\n          <div class=\"section-header\">\n            <span class=\"section-num\"\n              >Page 07</span\n            >\n            <h2>The Mineral Kingdom</h2>\n            <div\n              class=\"section-rule\"\n            ></div>\n          </div>\n          <div class=\"section-body\">\n            <div\n              class=\"section-content\"\n            >\n              <p>\n                <em>Evolutionary plan:\n                Physical awareness\n                (consciousness);\n                Hardness and beauty\n                (form)</em>\n              </p>\n              <h3>The Gods of Gold</h3>\n              <p>\n                There is a hierarchy of\n                Gods, the chord of whose\n                nature is identical with\n                that of gold. They may be\n                thought of as the divine\n                idea of gold manifest as\n                an Order of living beings.\n                Members of this hierarchy\n                are drawn by vibratory\n                affinity into the streams\n                of gold force which are\n                constantly descending\n                from the creative Source\n                into the physical world.\n                Their presence and\n                assistance intensify the\n                component frequencies and\n                thereby augment the\n                form-producing power of\n                the Word-force. Thus,\n                part of the function of\n                the Gods of gold, as also\n                of all Gods of the Order\n                of the Builders, is to\n                assist in the process of\n                the production of physical\n                substances and forms.\n              </p>\n            </div>\n          </div>\n          <div class=\"speaker-notes\">\n            <p class=\"notes-label\">\n              PLATE 18\n            </p>\n            <p>\n              A GOD OF THE GOLD REEF -\n              The vertical extension was\n              <em\n                >\"immense, reaching from\n                some two hundred feet in\n                the air to at least the\n                same distance below the\n                surface of the veldt,\n                whilst the actual\n                gold-producing force\n                played on down to the\n                reef, in some cases six\n                thousand or more feet\n                below.\"</em\n              >\n            </p>\n            <p>\n              <em\n                >\"The central figure was\n                unusually small for such\n                an auric extension,\n                being in this case\n                little more than eight\n                or ten feet tall. The\n                presiding God of the\n                Gold Reef is, however,\n                colossal in\n                stature.\"</em\n              >\n            </p>\n          </div>\n        </div>\n        <div\n          class=\"section-panel-image\"\n        >\n          <img\n            src=\"images/plate-7160905d-f7b0-4971-aada-4a3f086fbfb9.png\"\n            alt=\"Plate 18: A God of the Gold Reef - The Kingdom of the Gods, illustrated by Ethelwynne M. Quail\"\n          />\n          <div\n            class=\"panel-caption plate-trigger\"\n          >\n            PLATE 18 - A GOD OF THE GOLD\n            REEF\n          </div>\n        </div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 8 - The Plant Kingdom\n         ============================================================ -->\n      <section\n        class=\"page-section plant-carousel-section\"\n        id=\"page-08\"\n      >\n        <div class=\"section-header\">\n          <span class=\"section-num\"\n            >Page 08</span\n          >\n          <h2>The Plant Kingdom</h2>\n          <div\n            class=\"section-rule\"\n          ></div>\n        </div>\n\n        <div\n          class=\"section-body plant-carousel-body\"\n        >\n          <div class=\"section-content\">\n                          <p>\n                <em>Evolutionary plan:\n                Sensitivity and the\n                capacity to feel\n                (consciousness); Beauty\n                (form)</em>\n              </p>\n<p>\n                A vibratory possibility\n                is in the heart of every\n                seed. The seasonal\n                awakening produces a\n                subtle equivalent to\n                &quot;sound&quot;. This\n                &quot;sound&quot; is then\n                &quot;heard&quot; and the\n                nature spirit builders\n                answer the call. Every\n                stem, shoot, leaf and\n                flower has its own note,\n                to which the appropriate\n                builder responds.\n              </p>\n          </div>\n\n          <div\n            class=\"elemental-carousel plant-carousel\"\n          >\n            <div\n              class=\"carousel-track\"\n              id=\"plant-track\"\n            >\n              <div\n                class=\"carousel-slide\"\n              >\n                <div\n                  class=\"carousel-slide-text\"\n                >\n                  <h4>\n                    A Lord of the Tree Ferns\n                  </h4>\n                  <p>\n                    The tree fern God here\n                    portrayed was observed\n                    over the jungle in the\n                    mountain district of\n                    Ceylon. It is of interest\n                    to observe that the\n                    patterns formed by the\n                    flow of the lines of\n                    force in the aura of this\n                    God reproduce within it\n                    certain of the tree fern\n                    forms.\n                  </p>\n                </div>\n                <div\n                  class=\"carousel-slide-image\"\n                >\n                  <img\n                    src=\"images/plate-d27b267e-00dc-4fd5-966c-5575eec1be7b.png\"\n                    alt=\"A Lord of the Tree Ferns\"\n                  />\n                  <div class=\"panel-caption\">\n                    PLATE 5\n                  </div>\n                </div>\n              </div>\n              <div\n                class=\"carousel-slide\"\n              >\n                <div\n                  class=\"carousel-slide-text\"\n                >\n                  <h4>A Lord of the Pines</h4>\n                  <p>\n                    This being was observed\n                    in association with\n                    groups of stone pines in\n                    the Cape Peninsula,\n                    South Africa. As the\n                    picture shows, the\n                    coloring and the lines\n                    of force in the inner\n                    aura suggest somewhat\n                    the needlelike foliage\n                    of the pine. The stature\n                    of this God is about 30\n                    feet.\n                  </p>\n                </div>\n                <div\n                  class=\"carousel-slide-image\"\n                >\n                  <img\n                    src=\"images/plate-f549d2b0-3b5d-495b-844c-f27f1efc1e99.png\"\n                    alt=\"A Lord of the Pines\"\n                  />\n                  <div class=\"panel-caption\">\n                    PLATE 6\n                  </div>\n                </div>\n              </div>\n              <div\n                class=\"carousel-slide\"\n              >\n                <div\n                  class=\"carousel-slide-text\"\n                >\n                  <h4>\n                    A Tree Nature Spirit\n                  </h4>\n                  <p>\n                    This Waringan tree grew\n                    in a garden on the Island\n                    of Java.\n                  </p>\n                  <p>\n                    <em\n                      >\"When taking tea\n                      beneath its welcome\n                      shade, I became aware\n                      of the presence of\n                      this delightful tree\n                      nature spirit or dryad.\n                      I found it to be\n                      approaching\n                      individualisation, or\n                      evolution out of group\n                      into individualised\n                      consciousness.\"</em\n                    >\n                  </p>\n                </div>\n                <div\n                  class=\"carousel-slide-image\"\n                >\n                  <img\n                    src=\"images/plate-c9bf3c59-9aac-4267-a63e-9178c65b26af.png\"\n                    alt=\"A Tree Nature Spirit\"\n                  />\n                  <div class=\"panel-caption\">\n                    PLATE 7\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div\n              class=\"carousel-controls\"\n            >\n              <button\n                class=\"carousel-btn\"\n                id=\"plant-prev\"\n                onclick=\"window.__hiddenArchitectsGoPlant && window.__hiddenArchitectsGoPlant(-1); return false;\"\n              >\n                ◀\n              </button>\n              <div\n                class=\"carousel-dots\"\n              >\n                <span\n                  class=\"plant-dot active\"\n                  data-idx=\"0\"\n                  onclick=\"window.__hiddenArchitectsGoPlant && window.__hiddenArchitectsGoPlant(0, true); return false;\"\n                ></span>\n                <span\n                  class=\"plant-dot\"\n                  data-idx=\"1\"\n                  onclick=\"window.__hiddenArchitectsGoPlant && window.__hiddenArchitectsGoPlant(1, true); return false;\"\n                ></span>\n                <span\n                  class=\"plant-dot\"\n                  data-idx=\"2\"\n                  onclick=\"window.__hiddenArchitectsGoPlant && window.__hiddenArchitectsGoPlant(2, true); return false;\"\n                ></span>\n              </div>\n              <button\n                class=\"carousel-btn\"\n                id=\"plant-next\"\n                onclick=\"window.__hiddenArchitectsGoPlant && window.__hiddenArchitectsGoPlant(1); return false;\"\n              >\n                ▶\n              </button>\n            </div>\n          </div>\n        </div>\n        <div\n          class=\"speaker-notes\"\n        ></div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 9 - Devas: The Architects\n         ============================================================ -->\n      <section\n        class=\"page-section layout-image-right\"\n        id=\"page-09\"\n      >\n        <div class=\"section-panel-text\">\n          <div class=\"section-header\">\n            <span class=\"section-num\"\n              >Page 09</span\n            >\n            <h2>\n              The Greater Gods\n            </h2>\n            <div\n              class=\"section-rule\"\n            ></div>\n          </div>\n\n          <div class=\"section-body\">\n            <div class=\"section-content\">\n              <p>\n                The Greater Gods are the\n                architects -- the\n                Archangels, Devas, Angels,\n                and Sephiroth. In the\n                present Mahamanvantara\n                their will does not become\n                markedly differentiated\n                from the One Will. The\n                human sense of separated\n                personality is almost\n                entirely absent in them.\n                Their path of evolution\n                does not deeply penetrate\n                the physical world and\n                leads from instinctive to\n                self-conscious\n                co-operation with the One\n                Will. In preceding or\n                succeeding periods of\n                manifestation they either\n                have been or will be human.\n              </p>\n              <h3>\n                Their Active Role in Human\n                Life\n              </h3>\n              <p>\n                Their kingdom is not remote\n                or indifferent to human\n                life. Theosophical teaching\n                holds that every human\n                being has a guardian angel\n                - a deva whose specific\n                function is to accompany\n                that soul through its\n                incarnations, holding the\n                pattern of its higher self\n                and providing an invisible\n                source of protection,\n                inspiration, and guidance.\n                This is not metaphor. It\n                is a structural feature of\n                human existence that has\n                been attested across\n                virtually every spiritual\n                tradition in the world.\n              </p>\n            </div>\n          </div>\n          <div class=\"speaker-notes\">\n            <p class=\"notes-label\">\n              PLATE 20\n            </p>\n            <p>\n              <em\n                >&quot;True music is a\n                temporary, physical\n                expression of the sound\n                of the ever-uttered\n                &quot;Word&quot;. Throughout\n                creative Day, the Great\n                Breath is breathed upon\n                the Great Deep, which\n                responds as an aeolian\n                harp of myriad, vibrant\n                strings. As creative\n                Night draws near, the\n                Great Breath is breathed\n                in. Thereafter silence\n                reigns within the Great\n                Deep.&quot;</em\n              >\n            </p>\n          </div>\n        </div>\n        <div\n          class=\"section-panel-image\"\n        >\n          <img\n            src=\"images/plate-f43ed6e2-a731-4674-a8ed-8a06f4b7ea97.png\"\n            alt=\"Plate 20: An Angel of Music - The Kingdom of the Gods\"\n          />\n          <div class=\"panel-caption plate-trigger\">\n            PLATE 20 - AN ANGEL OF MUSIC\n          </div>\n        </div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 10 - The Mountain Gods\n         ============================================================ -->\n      <section\n        class=\"page-section mountain-gods-page\"\n        id=\"page-10\"\n      >\n        <div class=\"section-header\">\n          <span class=\"section-num\"\n            >Page 10</span\n          >\n          <h2>The Mountain Gods</h2>\n          <div\n            class=\"section-rule\"\n          ></div>\n        </div>\n\n        <div\n          class=\"section-body mountain-photo-body\"\n        >\n          <div class=\"section-content\">\n            <p>\n              Solar Archangels and\n              angels are represented by\n              corresponding planetary\n              Gods. There are angels\n              presiding over divisions\n              and areas of the surface\n              of the Earth. They are\n              called Landscape Angels.\n            </p>\n          </div>\n          <div class=\"mountain-photo-grid\">\n            <div\n              class=\"img-frame mountain-photo\"\n              title=\"PLATE 12\"\n            >\n              <img\n                src=\"images/plate-81639869-7d11-4edf-95a7-a092e3e1db5e.png\"\n                alt=\"PLATE 12: Fire God of the Table Mountain Range\"\n              />\n              <div class=\"panel-caption\">\n                PLATE 12\n              </div>\n            </div>\n            <div\n              class=\"img-frame mountain-photo\"\n              title=\"PLATE 9\"\n            >\n              <img\n                src=\"images/plate-f06ddd06-f3f6-4125-ba5c-847e7873dc65.png\"\n                alt=\"PLATE 9: Mountain God observed in the Drakensberg Range in Natal\"\n              />\n              <div class=\"panel-caption\">\n                PLATE 9\n              </div>\n            </div>\n            <div\n              class=\"img-frame mountain-photo\"\n              title=\"PLATE 13\"\n            >\n              <img\n                src=\"images/plate-f1ddc9f4-b840-43d5-ade8-d1a30c0a48d2.png\"\n                alt=\"PLATE 13: Mountain God near Castle Rock above Kirstenbosch Botanical Gardens\"\n              />\n              <div class=\"panel-caption\">\n                PLATE 13\n              </div>\n            </div>\n          </div>\n        </div>\n        <div\n          class=\"speaker-notes\"\n        ></div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 14 - The Insect Kingdom\n         ============================================================ -->\n      <section\n        class=\"page-section\"\n        id=\"page-14\"\n      >\n        <div class=\"section-header\">\n          <span class=\"section-num\"\n            >Page 14</span\n          >\n          <h2>The Insect Kingdom</h2>\n          <div\n            class=\"section-rule\"\n          ></div>\n        </div>\n\n        <div class=\"section-body\">\n          <div class=\"section-content insect-kingdom-content\">\n            <p>\n              An Angelic Order exists\n              which has evolved through\n              the insect-branch of\n              Nature.\n            </p>\n            <div class=\"insect-image-row\">\n              <div class=\"insect-image-frame img-frame\">\n                <img\n                  src=\"images/insects.jpg\"\n                  alt=\"Insects representing the insect branch of Nature\"\n                />\n              </div>\n              <div class=\"insect-side-text\">\n                <p>\n                  Just as Monads\n                  manifested through other\n                  facets of divine\n                  ideation are guarded and\n                  aided by their\n                  evolutionary seniors, so\n                  are those who, when\n                  their Rays first touch\n                  the physical world, find\n                  their embodiment as\n                  thousands of tiny\n                  insects.\n                </p>\n                <p>\n                  They pass their physical\n                  existence and achieve all\n                  that is desired of them\n                  by passage through that\n                  kingdom as butterflies,\n                  bees, beetles, ants or\n                  other leading examples of\n                  the insect Ray types, and\n                  pass on to the\n                  superphysical worlds\n                  through which first as\n                  nature spirits and later\n                  as rupa and arupa devas,\n                  they ascend to\n                  Archangelic heights and\n                  beyond.\n                </p>\n              </div>\n            </div>\n          </div>\n        </div>\n        <div\n          class=\"speaker-notes\"\n        ></div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 11 - Angelic Hierarchies\n         ============================================================ -->\n      <section\n        class=\"page-section layout-image-right\"\n        id=\"page-11\"\n      >\n        <div class=\"section-panel-text\">\n          <div class=\"section-header\">\n            <span class=\"section-num\"\n              >Page 11</span\n            >\n            <h2>\n              Angelic Hierarchies\n            </h2>\n            <div\n              class=\"section-rule\"\n            ></div>\n          </div>\n\n          <div class=\"section-body\">\n            <div class=\"section-content\">\n              <p>\n                The totality of Angelic\n                Hosts and Nature Spirits\n                of a solar system is a\n                manifestation of one Solar\n                Archangel of unimaginable\n                splendor within whom all\n                angels live. From this\n                center all have emanated,\n                and into it all will\n                return.\n              </p>\n              <p>\n                The One Supreme Being\n                becomes expressed in 3\n                aspects: masculine,\n                androgyne, and feminine.\n                These 3 emanations in turn\n                unite every possible\n                combination to produce a\n                7-fold self-expression of\n                the Divine Monad. These are\n                the 7 highest Archangels.\n              </p>\n              <p>\n                There are many, many\n                Archangels and Angels\n                including:\n              </p>\n              <ul>\n                <li>\n                  Planetary Archangels\n                </li>\n                <li>National Angels</li>\n                <li>\n                  Angel builders of human\n                  form\n                </li>\n                <li>Angels of Religion</li>\n                <li>\n                  Group soul Angels for\n                  the mineral, plant, and\n                  animal kingdoms\n                </li>\n              </ul>\n            </div>\n          </div>\n        </div>\n        <div\n          class=\"section-panel-image\"\n        >\n          <img\n            src=\"images/plate-ce15032a-034e-4721-a0a4-c4e1452be609.png\"\n            alt=\"Plate 27: A Kundalini Devi - The Kingdom of the Gods\"\n          />\n          <div class=\"panel-caption\">\n            PLATE 27 - A KUNDALINI DEVI\n          </div>\n        </div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 12 - Angelic Healing\n         ============================================================ -->\n      <section\n        class=\"page-section layout-image-right healing-page\"\n        id=\"page-12\"\n      >\n        <div class=\"section-panel-text\">\n          <div class=\"section-header\">\n            <span class=\"section-num\"\n              >Page 12</span\n            >\n            <h2>Angelic Healing</h2>\n            <div\n              class=\"section-rule\"\n            ></div>\n          </div>\n\n          <div class=\"section-body\">\n            <div class=\"section-content\">\n              <p>\n                These pictures portray\n                three different types of\n                angels engaged in their\n                healing ministry.\n              </p>\n              <p> The\n                general method is first\n                to direct streams of\n                purifying energy into and\n                through the aura of the\n                sufferer, in order to\n                disperse congestions in\n                the etheric and emotional\n                bodies especially and to\n                drive out harmful\n                substances. They then\n                re-attune the chord of\n                &quot;Word&quot; of the\n                individual, usually\n                dissonant in the psyche\n                during ill-health, and\n                try to restore the\n                harmonious and rhythmic\n                flow of the inner\n                Life-forces throughout\n                the mental, emotional and\n                physical nature. Finally,\n                they invoke divine healing\n                power from its Source\n                into the patients. Such\n                ministrations are far\n                more effective when man\n                consciously invokes and\n                cooperates with the\n                healing angels.\n              </p>\n            </div>\n          </div>\n        </div>\n        <div\n          class=\"section-panel-image healing-image-stack\"\n        >\n          <div class=\"img-frame healing-image-frame\">\n            <img\n              src=\"images/plate-7409cf24-1fe0-4c27-ba31-dc6c2f06713b.png\"\n              alt=\"Plate 23: Angelic healing ministry\"\n            />\n            <div class=\"panel-caption\">\n              PLATE 23\n            </div>\n          </div>\n          <div class=\"img-frame healing-image-frame\">\n            <img\n              src=\"images/plate-c19c5645-0051-40ba-afe2-c423e223135f.png\"\n              alt=\"Plate 24: Angelic healing ministry\"\n            />\n            <div class=\"panel-caption\">\n              PLATE 24\n            </div>\n          </div>\n          <div class=\"img-frame healing-image-frame\">\n            <img\n              src=\"images/plate-d4c50a1d-c4e3-4429-8ad4-6e4f0cc77111.png\"\n              alt=\"Plate 25: Angelic healing ministry\"\n            />\n            <div class=\"panel-caption\">\n              PLATE 25\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 13 - The Miracle of Birth\n         ============================================================ -->\n      <section\n        class=\"page-section layout-image-right healing-page miracle-birth-page\"\n        id=\"page-13\"\n      >\n        <div class=\"section-panel-text\">\n          <div class=\"section-header\">\n            <span class=\"section-num\"\n              >Page 13</span\n            >\n            <h2>The Miracle of Birth</h2>\n            <div\n              class=\"section-rule\"\n            ></div>\n          </div>\n\n          <div class=\"section-body\">\n            <div class=\"section-content\">\n              <p>\n                During the descent into\n                incarnation of each life\n                cycle, angels are present\n                and assist in the dual\n                process of the\n                construction of the new\n                bodies - mental,\n                emotional, etheric, and\n                physical - and the\n                induction into them of\n                the reincarnating ego.\n              </p>\n              <p>\n                Universal substance, or\n                prakriti, is the womb\n                wherein all worlds\n                gestate, from which all\n                are born and to which all\n                return. The true World\n                Mother is this primary\n                substance of a universe\n                when first differentiated\n                from the root of matter\n                or mulaprakriti; therein\n                reside the seeds of all\n                living things and the\n                powers of conservation\n                and reproduction.\n              </p>\n              <p>\n                The planetary World\n                Mother is beyond all\n                limitation of form. No\n                picture can truly\n                represent Her. Plate 28\n                shows her in a\n                Madonna-like form, and\n                her ministering angels\n                appear in close\n                association with a mother\n                and her unborn child as\n                the time of birth draws\n                near. Plate 29\n                symbolically portrays her\n                in Her solar aspect,\n                brooding in divine love\n                over all worlds.\n              </p>\n            </div>\n          </div>\n        </div>\n        <div\n          class=\"section-panel-image healing-image-stack\"\n        >\n          <div class=\"img-frame healing-image-frame\">\n            <img\n              src=\"images/plate-b82b8404-2a11-40d9-ba1a-e098e7fd2e20.png\"\n              alt=\"Plate 28: The Miracle of Birth\"\n            />\n            <div class=\"panel-caption\">\n              PLATE 28 - THE MIRACLE OF BIRTH\n            </div>\n          </div>\n          <div class=\"img-frame healing-image-frame\">\n            <img\n              src=\"images/plate-water-angel.png\"\n              alt=\"Plate 29: The World Mother\"\n            />\n            <div class=\"panel-caption\">\n              PLATE 29 - THE WORLD MOTHER\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- ============================================================\n         PAGE 16 - Rediscovering the Hidden Kingdoms\n         ============================================================ -->\n      <section\n        class=\"page-section\"\n        id=\"page-16\"\n      >\n        <div class=\"section-header\">\n          <span class=\"section-num\"\n            >Page 15</span\n          >\n          <h2>\n            Rediscovering the Hidden\n            Kingdoms\n          </h2>\n          <div\n            class=\"section-rule\"\n          ></div>\n        </div>\n\n        <div class=\"section-body\">\n          <div class=\"section-content\">\n            <p>\n              Annie Besant spoke of the\n              coming Aquarian age as a\n              period in which the\n              relationship between the\n              human and deva kingdoms\n              would be consciously\n              restored - not as the\n              fitful, uncertain\n              perceptions of gifted\n              individuals, but as a\n              recognized reality\n              integrated into the fabric\n              of civilization. In this\n              vision, cooperation with\n              the angelic and elemental\n              worlds would inform\n              agriculture, medicine,\n              education, the arts, and\n              the governance of nations.\n            </p>\n\n            <p>\n              <em>&quot;The Aquarian age will\n              see a new relationship\n              between humanity and the\n              deva kingdom - one of\n              conscious cooperation,\n              mutual recognition, and\n              shared service to the\n              evolving life of the\n              planet.&quot;</em>\n            </p>\n\n            <p>\n              These kingdoms have not\n              gone away. They have been\n              present throughout every\n              epoch of human history,\n              working ceaselessly in the\n              natural world, responsive\n              to human attention and\n              intention. What has\n              changed is our willingness\n              - or ability - to perceive\n              them.\n            </p>\n\n            <div class=\"practice-cards\">\n              <div class=\"practice-card\">\n                <div class=\"practice-icon\">\n                  🌿\n                </div>\n                <h4>\n                  Spend Time in Nature\n                </h4>\n                <p>\n                  The nature spirits are\n                  most perceptible to a\n                  still, attentive, and\n                  genuinely open\n                  consciousness. Sit by\n                  water. Walk in woods.\n                </p>\n              </div>\n              <div class=\"practice-card\">\n                <div class=\"practice-icon\">\n                  ✦\n                </div>\n                <h4>\n                  Open Heart and Mind\n                </h4>\n                <p>\n                  Approach these kingdoms\n                  with genuine openness,\n                  without demand, and\n                  with the expectation of\n                  a response. The deva\n                  kingdom, in particular,\n                  is highly responsive to\n                  sincere aspiration.\n                </p>\n              </div>\n              <div class=\"practice-card\">\n                <div class=\"practice-icon\">\n                  ☀\n                </div>\n                <h4>\n                  Direct Thought\n                  Intentionally\n                </h4>\n                <p>\n                  We can reach toward\n                  them through directed,\n                  selfless thought. A\n                  genuinely loving,\n                  generous thought sent\n                  toward the nature of a\n                  place or the being of a\n                  tree is not wasted.\n                </p>\n              </div>\n            </div>\n          </div>\n        </div>\n        <div\n          class=\"speaker-notes\"\n        ></div>\n      </section>\n\n      <!-- FOOTER (inside last snap section) -->\n      <footer>\n        <p>\n          A Theosophical Presentation\n          &mdash;\n          <em\n            >The Hidden Architects:\n            Nature's Invisible\n            Kingdoms</em\n          >\n        </p>\n        <p\n          style=\"\n            margin-top: 0.5rem;\n            opacity: 0.5;\n          \"\n        >\n          Based on the work of Geoffrey\n          Hodson &bull; Tim Wyatt &bull;\n          Annie Besant &bull; Rudolf\n          Steiner\n        </p>\n      </footer>\n\n      <!-- ============================================================\n         PAGE 17 - L'Envoi\n         ============================================================ -->\n      <section\n        class=\"page-section layout-image-right\"\n        id=\"page-17\"\n      >\n        <div class=\"section-panel-text\">\n          <div class=\"section-header\">\n            <span class=\"section-num\"\n              >Page 16</span\n            >\n            <h2>L'Envoi</h2>\n            <div\n              class=\"section-rule\"\n            ></div>\n          </div>\n          <div class=\"section-body\">\n            <div\n              class=\"section-content\"\n            >\n              <p>\n                <em\n                  >\"The Gods await the\n                  conscious re-union of\n                  the mind of man with\n                  the Universal Mind.\n                  Humanity awakens\n                  slowly. Matter-blinded\n                  through centuries, few\n                  men as yet perceive\n                  the mind within the\n                  substance, the life\n                  within the form.</em\n                >\n              </p>\n              <p>\n                <em\n                  >In search of power\n                  and wealth, men have\n                  traversed the whole\n                  earth, have penetrated\n                  the wilds, scaled the\n                  peaks and conquered\n                  the polar wastes. Let\n                  them now seek within\n                  the form, scale the\n                  heights of their own\n                  consciousness,\n                  penetrate its depth,\n                  in search of that\n                  inner Power and Life\n                  by which alone they\n                  may become strong in\n                  will and spiritually\n                  enriched.</em\n                >\n              </p>\n              <p>\n                <em\n                  >He who thus throws\n                  open his life and mind\n                  to the Universal Life\n                  and Mind indwelling in\n                  all things will enter\n                  into union therewith\n                  and to him the Gods\n                  will appear.\"</em\n                >\n              </p>\n            </div>\n          </div>\n          <div\n            class=\"speaker-notes\"\n          ></div>\n        </div>\n        <div\n          class=\"section-panel-image\"\n        >\n          <img\n            src=\"images/plate-fire.png\"\n            alt=\"Plate 8: A Mountain God - The Kingdom of the Gods, illustrated by Ethelwynne M. Quail\"\n          />\n          <div class=\"panel-caption\">\n            PLATE 8 - A MOUNTAIN GOD\n          </div>\n        </div>\n      </section>\n      <!-- ============================================================\n         PAGE 18 - References\n         ============================================================ -->\n      <section\n        class=\"page-section\"\n        id=\"page-18\"\n      >\n        <div class=\"section-header\">\n          <span class=\"section-num\"\n            >Page 17</span\n          >\n          <h2>References</h2>\n          <div\n            class=\"section-rule\"\n          ></div>\n        </div>\n\n        <div class=\"section-body\">\n          <div class=\"section-content references-list\">\n            <p>\n              INFO: <a\n                href=\"https://theosophy.world/encyclopedia/subba-row-medal\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                >Subba Row Medal</a\n              >\n            </p>\n            <p>\n              FULL TEXT: <a\n                href=\"https://www.theosophy.world/sites/default/files/ebooks/The%20Kingdom%20of%20the%20Gods%20-%20Geoffrey%20Hodson.pdf\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                >The Kingdom of the Gods</a\n              >\n            </p>\n            <p>\n              VIDEO: <a\n                href=\"https://www.youtube.com/@NewThinkingAllowed\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                >New Thinking Allowed channel</a\n              >\n            </p>\n            <p>\n              VIDEO: <a\n                href=\"https://www.youtube.com/embed/7WGssopZcig\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                >Jeffrey Mishlove on Geoffrey Hodson</a\n              >\n            </p>\n            <p>\n              PURCHASE: <a\n                href=\"https://www.amazon.com/Fairies-Work-Play-Quest-Book/dp/0835605531\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                >Fairies at Work and at Play by Geoffrey Hodson</a\n              >\n            </p>\n            <p>\n              PURCHASE: <a\n                href=\"https://www.amazon.com/Passport-Magonia-Folklore-Flying-Saucers-ebook/dp/B00TU7V0XA?ref_=ast_author_mpb\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                >Passport to Magonia: From Folklore to Flying Saucers</a\n              >\n            </p>\n            <p>\n              VIDEO: <a\n                href=\"https://www.youtube.com/embed/5L1p4uXcJKo?si=CmnPh4tXjP4dmB_d\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                >Fairy Pancakes</a\n              >\n            </p>\n            <p>\n              VIDEO: <a\n                href=\"https://www.youtube.com/watch?v=d_RGEpJSr6s\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                >Rupert Sheldrake's Morphic Resonance</a\n              >\n            </p>\n            <p>\n              ARTICLE: <a\n                href=\"https://www.newdawnmagazine.com/articles/newscience-consciousness/morphic-resonance-morphic-fields-collective-memory-the-habits-of-nature\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                >Morphic Resonance &amp; Morphic Fields: Collective Memory &amp; the Habits of Nature</a\n              >\n            </p>\n            <p>\n              ARTICLE: <a\n                href=\"https://www.chemistryworld.com/features/the-curious-case-of-disappearing-polymorphs/4023257.article\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                >The Curious Case of Disappearing Polymorphs</a\n              >\n            </p>\n          </div>\n        </div>\n        <div\n          class=\"speaker-notes\"\n        ></div>\n      </section>\n\n    </main>\n\n    <!-- Slide Controls -->\n    <div id=\"slide-controls\">\n      <button\n        id=\"prev-btn\"\n        aria-label=\"Previous section\"\n      >\n        ◀\n      </button>\n      <span id=\"slide-counter\"\n        >01 / 17</span\n      >\n      <button\n        id=\"next-btn\"\n        aria-label=\"Next section\"\n      >\n        ▶\n      </button>\n    </div>";
